// Normalize Projects Data (v2) - STRONG DONE DETECTION
// - Marks card as done if:
//   1) Trello dueComplete === true
//   2) card.closed === true (archived)
//   3) list name indicates completion (Arabic/English keywords like "إنجاز شهر يناير")

const cards = $items("Get Cards").map(i => i.json);
const lists = $items("Get Lists").map(i => i.json);

// Map listId -> listName
const listMap = {};
for (const l of lists) listMap[l.id] = l.name || "";

// Helpers
function uniq(arr) {
  return [...new Set((arr || []).filter(Boolean))];
}

function normalizeText(s) {
  return (s || "")
    .toString()
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

// Detect done list names (add your org naming patterns here)
function isDoneList(listName) {
  const n = normalizeText(listName);

  // ✅ كلمات إنجاز/إغلاق/أرشفة عربية شائعة + إنجليزية
  const doneKeywords = [
    "done", "completed", "complete", "closed", "finished", "final", "archive", "archived",
    "تم", "مكتمل", "منجز", "منجزة", "إنجاز", "انجاز", "إغلاق", "اغلاق", "مغلق", "مقفلة", "مقفل",
    "أرشيف", "ارشيف", "مؤرشف", "مؤرشفة", "منتهي", "منتهية", "تم الإنهاء", "تم الانتهاء"
  ];

  // ✅ نمط قوائم مثل: "إنجاز شهر يناير" / "انجاز شهر فبراير"
  const donePatterns = [
    "انجاز شهر", "إنجاز شهر",
    "انجاز", "إنجاز"
  ];

  if (doneKeywords.some(k => n.includes(normalizeText(k)))) return true;
  if (donePatterns.some(k => n.includes(normalizeText(k)))) return true;

  return false;
}

return cards.map(card => {
  const listName = listMap[card.idList] || "غير مصنف";

  // team members
  const members = Array.isArray(card.members)
    ? uniq(card.members.map(m => m.fullName || m.username || m.id))
    : [];

  const dueComplete = card.dueComplete === true;     // Trello built-in
  const isArchived = card.closed === true;          // Trello archived card
  const doneByList = isDoneList(listName);          // by list naming

  const isDone = (dueComplete || isArchived || doneByList) ? true : false;

  return {
    json: {
      project_id: card.id,
      project_name: card.name || "(بدون اسم)",
      project_category: listName,

      due_date: card.due || null,

      team_members: members,

      // ✅ status helpers used by KPIs
      due_complete: dueComplete,
      is_archived: isArchived,
      is_done_list: doneByList,
      is_done: isDone,

      _raw: {
        idList: card.idList,
        closed: isArchived
      }
    }
  };
});

// Executive KPIs v7 - مع المستهدفات السنوية الثابتة للفئات الست
// Window: now -> now + windowDays

const projects = $input.all().map(i => i.json);

// ✅ غيّر هنا لو تبي 30 / 14 / 7 ... الخ
const windowDays = 30;

const now = new Date();
const windowEnd = new Date(now.getTime() + windowDays * 24 * 60 * 60 * 1000);

// ====== Helpers ======
function safeDate(s) {
  if (!s) return null;
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

function uniq(arr) {
  return [...new Set((arr || []).filter(Boolean))];
}

function pct(num, den) {
  if (!den) return 0;
  return Math.round((num / den) * 1000) / 10;
}

function formatISODate(d) {
  if (!d) return null;
  return d.toISOString().split("T")[0];
}

const todayDay = formatISODate(now);

function isOverdueByDay(dueDateObj) {
  if (!dueDateObj) return false;
  const dueDay = formatISODate(dueDateObj);
  return !!(dueDay && dueDay < todayDay);
}

function isDone(p) {
  return p.is_done === true || p.due_complete === true || p.is_done_list === true;
}

// ✅ تطبيع النصوص العربية
function normalizeArabic(s) {
  return (s || "")
    .toString()
    .trim()
    .replace(/\s+/g, " ")
    .replace(/[إأآا]/g, "ا")
    .replace(/ى/g, "ي")
    .replace(/ة/g, "ه")
    .replace(/[\u064B-\u0652]/g, "");
}

// ====== 0) Normalize + add helper fields ======
const normalized = projects.map(p => {
  const _due = safeDate(p.due_date);
  const _members = uniq(p.team_members);
  const _category = p.project_category || "غير مصنف";
  const _name = p.project_name || "(بدون اسم)";

  return {
    ...p,
    _due,
    _members,
    _category,
    _name,
    _due_day: _due ? formatISODate(_due) : null,
    _is_done: isDone(p),
    _is_overdue: _due ? (isOverdueByDay(_due) && !isDone(p)) : false,
  };
});

// ====== 1) ALL counters ======
const total_all = normalized.length;

const overdue_all_list = normalized
  .filter(p => p._is_overdue)
  .sort((a, b) => (a._due - b._due));

const overdue_all = overdue_all_list.length;
const missing_due_all = normalized.filter(p => !p._due).length;
const unassigned_all = normalized.filter(p => p._members.length === 0).length;

// ====== 2) Window set ======
const due_within_window = normalized
  .filter(p => p._due && p._due >= now && p._due <= windowEnd && !p._is_done)
  .sort((a, b) => a._due - b._due);

const total_window = due_within_window.length;

const window_by_category = {};
for (const p of due_within_window) {
  window_by_category[p._category] = (window_by_category[p._category] || 0) + 1;
}

const top_category = Object.entries(window_by_category)
  .map(([category, count]) => ({ category, count }))
  .sort((a, b) => b.count - a.count)[0] || { category: "—", count: 0 };

// ====== 3) Workload per member ======
const window_by_member = {};
for (const p of due_within_window) {
  for (const m of p._members) {
    window_by_member[m] = (window_by_member[m] || 0) + 1;
  }
}

const window_projects_per_member_sorted = Object.entries(window_by_member)
  .map(([member, count]) => ({ member, count }))
  .sort((a, b) => b.count - a.count);

const top_member = window_projects_per_member_sorted[0] || { member: "—", count: 0 };
const window_top_members = window_projects_per_member_sorted.slice(0, 10);

// ====== 4) Matrix ======
const window_member_category_matrix = {};
for (const p of due_within_window) {
  for (const m of p._members) {
    if (!window_member_category_matrix[m]) window_member_category_matrix[m] = {};
    window_member_category_matrix[m][p._category] = (window_member_category_matrix[m][p._category] || 0) + 1;
  }
}

// ====== 5) Window projects list ======
const window_projects_list = due_within_window.map(p => ({
  project_id: p.project_id,
  project_name: p._name,
  project_category: p._category,
  due_date: p.due_date,
  due_day: p._due_day,
  team_members: p._members,
  team_size: p._members.length,
}));

const due_soon_top20 = window_projects_list.slice(0, 20);

// ====== 6) Overdue list ======
const overdue_projects_list = overdue_all_list.map(p => ({
  project_id: p.project_id,
  project_name: p._name,
  project_category: p._category,
  due_date: p.due_date,
  due_day: p._due_day,
  team_members: p._members,
  team_size: p._members.length,
}));

const overdue_projects_table_rows = overdue_projects_list.map(p => ({
  project_name: p.project_name,
  project_category: p.project_category,
  due_day: p.due_day || "—",
  team: (p.team_members && p.team_members.length) ? p.team_members.join(", ") : "لا يوجد"
}));

// ====== 7) Render-ready lines ======
const window_breakdown_lines = Object.entries(window_by_category)
  .sort((a, b) => b[1] - a[1])
  .map(([category, count]) => `${category}: ${count}`);

const window_top_members_lines = window_top_members
  .map(x => `${x.member}: ${x.count}`);

// ====== 8) ✅ المبادرات في الفئات الرئيسية الست (مع المستهدفات السنوية) ======
// المطابقة على "اسم البطاقة" (project_name)
// المستهدف ثابت سنوياً، والإنجاز = عدد البطاقات المنجزة فعلياً ÷ المستهدف
const targetCategoryDefinitions = [
  { name: "تستاهل الصيت",                target: 9  },
  { name: "باختصار",                     target: 6  },
  { name: "رحلة المنظومة",               target: 11 },
  { name: "المنجزات الوزارة والمنظومة", target: 12 },
  { name: "نبذة تعريفية",                target: 6  },
  { name: "مبادرة جسور المنظومة",       target: 1  }
];

function matchInitiativeByName(cardName, targetName) {
  const c = normalizeArabic(cardName);
  const t = normalizeArabic(targetName);
  return c.includes(t);
}

const target_initiatives = targetCategoryDefinitions.map(def => {
  const matched = normalized.filter(p => matchInitiativeByName(p._name, def.name));
  const completed = matched.filter(p => p._is_done);
  const inProgress = matched.filter(p => !p._is_done);

  // نسبة الإنجاز محسوبة من المستهدف وليس من إجمالي البطاقات
  const achievement_pct = def.target ? Math.round((completed.length / def.target) * 1000) / 10 : 0;

  return {
    name: def.name,
    target: def.target,
    total_cards: matched.length,
    completed_count: completed.length,
    in_progress_count: inProgress.length,
    remaining_to_target: Math.max(def.target - completed.length, 0),
    achievement_pct,
    completed_projects: completed.map(p => p._name),
    in_progress_projects: inProgress.map(p => p._name)
  };
});

// ====== KPIs object ======
const kpis = {
  window_days: windowDays,
  window_start_iso: now.toISOString(),
  window_end_iso: windowEnd.toISOString(),
  window_start_day: formatISODate(now),
  window_end_day: formatISODate(windowEnd),

  all: {
    total_projects: total_all,
    overdue_projects: overdue_all,
    missing_due_projects: missing_due_all,
    unassigned_projects: unassigned_all,
    overdue_rate_pct: pct(overdue_all, total_all),
    missing_due_rate_pct: pct(missing_due_all, total_all),
    unassigned_rate_pct: pct(unassigned_all, total_all),
  },

  window: {
    due_within_window: total_window,
    due_within_window_rate_pct: pct(total_window, total_all),
    top_category,
    top_member,
  }
};

return [{
  json: {
    generated_at: now.toISOString(),
    kpis,

    breakdowns: {
      window_by_category,
      window_projects_per_member_sorted,
      window_top_members,
      window_member_category_matrix,
    },

    projects_within_window: window_projects_list,
    overdue_projects: overdue_projects_list,

    highlights: {
      top_category_in_window: top_category,
      top_member_in_window: top_member,
      due_soon_top20,
    },

    target_initiatives,

    render_ready: {
      window_breakdown_lines,
      window_top_members_lines,
      window_label: `${formatISODate(now)} → ${formatISODate(windowEnd)}`,
      overdue_projects_table_rows
    }
  }
}];

// ============================================================
// التقرير التنفيذي الكامل - متوافق مع Outlook + Gmail + Apple Mail
// مع spacer rows لضمان المسافات الداخلية في Outlook
// ============================================================

// ---------- 1) قراءة نص ChatGPT ----------
function pickTextFromChatGPT(item) {
  const out = item.output;
  if (Array.isArray(out) && out[0]?.content?.[0]?.text) return out[0].content[0].text;
  if (item.content?.[0]?.text) return item.content[0].text;
  if (typeof item.text === "string") return item.text;
  return null;
}

let aiSummary = "";
let aiInsight = "";
let aiRecommendations = [];
try {
  const raw = pickTextFromChatGPT($json);
  if (raw) {
    let parsed;
    try {
      parsed = JSON.parse(raw);
    } catch (e) {
      const first = raw.indexOf("{");
      const last = raw.lastIndexOf("}");
      if (first >= 0 && last > first) parsed = JSON.parse(raw.slice(first, last + 1));
    }
    aiSummary = parsed?.executive_summary || "";
    aiInsight = parsed?.analytical_insight || "";
    aiRecommendations = Array.isArray(parsed?.recommendations) ? parsed.recommendations : [];
  }
} catch (e) { /* fallback */ }

// ---------- 2) قراءة بيانات KPIs ----------
const kpisData = $('Executive KPIs').first().json;
const k = kpisData.kpis;
const all = k.all;
const win = k.window;
const breakdowns = kpisData.breakdowns || {};
const overdueProjects = kpisData.overdue_projects || [];
const dueSoon = kpisData.highlights?.due_soon_top20 || [];
const targetInitiatives = kpisData.target_initiatives || [];

// ---------- 3) لوحة الألوان ----------
const C = {
  navy:       '#1B3A57',
  gold:       '#C8A55C',
  ink:        '#1A1A1A',
  muted:      '#6B7280',
  card:       '#F8F9FB',
  cardDanger: '#FEF2F2',
  border:     '#E5E7EB',
  danger:     '#B91C1C',
  warn:       '#D97706',
  ok:         '#059669',
  bg:         '#FFFFFF'
};

const periodStart = k.window_start_day;
const periodEnd   = k.window_end_day;

// ---------- 4) ملخص افتراضي ----------
if (!aiSummary) {
  aiSummary = `يستعرض هذا التقرير أداء محفظة المشاريع للفترة من ${periodStart} إلى ${periodEnd}، وتضم ${all.total_projects} مشروعاً. تبلغ نسبة المشاريع المتأخرة ${all.overdue_rate_pct}%، مع ${all.missing_due_projects} مشروعاً دون تاريخ استحقاق محدد، و${all.unassigned_projects} مشروعاً غير مُسند لمالك.`;
}

// ---------- 5) توصيات افتراضية ----------
if (!aiRecommendations.length) {
  const fallback = [];
  if (all.overdue_projects > 0) {
    fallback.push(`مراجعة المشاريع المتأخرة البالغ عددها ${all.overdue_projects} مشروعاً مع المسؤولين المباشرين خلال أسبوع لتحديد أسباب التأخر ووضع خطة استدراك.`);
  }
  if (all.missing_due_projects > 0) {
    fallback.push(`تحديد تواريخ استحقاق لـ ${all.missing_due_projects} مشروعاً تفتقد التواريخ خلال 5 أيام عمل لضمان قابلية المتابعة.`);
  }
  if (all.unassigned_projects > 0) {
    fallback.push(`إسناد ${all.unassigned_projects} مشروعاً غير مُسند إلى مالكين محددين لضمان وضوح المسؤوليات.`);
  }
  if (!fallback.length) {
    fallback.push("الحفاظ على وتيرة الأداء الحالية مع متابعة دورية للمشاريع القادمة في النافذة التشغيلية.");
  }
  aiRecommendations = fallback;
}

// ---------- 6) شارة المخاطر ----------
const riskLevel = all.overdue_rate_pct >= 30 ? { label: 'مرتفع', color: C.danger }
                : all.overdue_rate_pct >= 15 ? { label: 'متوسط', color: C.warn }
                : { label: 'منخفض', color: C.ok };

// ---------- 7) دوال البناء ----------

// ✅ KPI Card مع spacer rows
const kpiCard = (label, value, sub, color) => `
  <td width="25%" valign="top" style="padding:6px;">
    <table width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${C.card}" style="background-color:${C.card};border:1px solid ${C.border};border-right:3px solid ${color};">
      <tr><td height="18" style="font-size:1px;line-height:18px;">&nbsp;</td></tr>
      <tr><td style="padding:0 20px;font-family:Tahoma,Arial,sans-serif;font-size:11px;color:${C.muted};letter-spacing:0.5px;">${label}</td></tr>
      <tr><td height="8" style="font-size:1px;line-height:8px;">&nbsp;</td></tr>
      <tr><td style="padding:0 20px;font-family:Tahoma,Arial,sans-serif;font-size:28px;color:${C.ink};font-weight:700;line-height:1;">${value}</td></tr>
      <tr><td height="6" style="font-size:1px;line-height:6px;">&nbsp;</td></tr>
      <tr><td style="padding:0 20px;font-family:Tahoma,Arial,sans-serif;font-size:11px;color:${color};font-weight:600;">${sub}</td></tr>
      <tr><td height="18" style="font-size:1px;line-height:18px;">&nbsp;</td></tr>
    </table>
  </td>`;

// ✅ Section Title
const sectionTitle = (num, title) => `
  <tr><td style="padding:28px 0 12px 0;font-family:Tahoma,Arial,sans-serif;">
    <table cellpadding="0" cellspacing="0" border="0"><tr>
      <td bgcolor="${C.navy}" style="background-color:${C.navy};color:#fff;font-size:11px;font-weight:700;padding:4px 10px;letter-spacing:1px;">${num}</td>
      <td style="padding:0 10px;font-size:16px;color:${C.ink};font-weight:700;">${title}</td>
    </tr></table>
    <table width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:8px;"><tr>
      <td bgcolor="${C.border}" height="1" style="background-color:${C.border};font-size:1px;line-height:1px;">&nbsp;</td>
    </tr></table>
  </td></tr>`;

// ✅ شريط تقدّم متوافق مع Outlook
const progressBar = (label, count, max, color) => {
  const pct = max ? Math.round((count/max)*100) : 0;
  const fillPct = Math.max(pct, 1);
  const emptyPct = 100 - fillPct;

  const fillCell = `<td width="${fillPct}%" height="14" bgcolor="${color}" style="background-color:${color};font-size:1px;line-height:14px;">&nbsp;</td>`;
  const emptyCell = emptyPct > 0
    ? `<td width="${emptyPct}%" height="14" bgcolor="${C.border}" style="background-color:${C.border};font-size:1px;line-height:14px;">&nbsp;</td>`
    : '';

  return `
  <tr><td style="padding:6px 0;font-family:Tahoma,Arial,sans-serif;">
    <table width="100%" cellpadding="0" cellspacing="0" border="0" dir="rtl"><tr>
      <td width="35%" style="font-size:12px;color:${C.ink};padding-left:10px;font-family:Tahoma,Arial,sans-serif;">${label}</td>
      <td width="55%">
        <table width="100%" cellpadding="0" cellspacing="0" border="0" dir="rtl" style="border-collapse:collapse;">
          <tr>${fillCell}${emptyCell}</tr>
        </table>
      </td>
      <td width="10%" style="font-size:12px;color:${C.muted};text-align:left;padding-right:10px;font-weight:600;font-family:Tahoma,Arial,sans-serif;">${count}</td>
    </tr></table>
  </td></tr>`;
};

// ✅ Initiative Card مع spacer rows متوافقة مع Outlook
const initiativeCard = (item) => {
  const pct = item.achievement_pct;
  const accent = pct >= 90 ? C.ok
               : pct >= 60 ? C.gold
               : pct >= 30 ? C.warn
               : C.danger;
  const statusLabel = pct >= 90 ? 'تحقق المستهدف'
                    : pct >= 60 ? 'على المسار'
                    : pct >= 30 ? 'يحتاج تسريع'
                    : 'متأخر عن المستهدف';

  const barFill = Math.min(Math.max(pct, 1), 100);
  const barEmpty = 100 - barFill;

  const barFillCell = `<td width="${barFill}%" height="6" bgcolor="${accent}" style="background-color:${accent};font-size:1px;line-height:6px;">&nbsp;</td>`;
  const barEmptyCell = barEmpty > 0
    ? `<td width="${barEmpty}%" height="6" bgcolor="${C.border}" style="background-color:${C.border};font-size:1px;line-height:6px;">&nbsp;</td>`
    : '';

  return `
    <td width="33%" valign="top" style="padding:6px;">
      <table width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${C.card}" style="background-color:${C.card};border:1px solid ${C.border};border-right:3px solid ${accent};">

        <tr><td height="16" style="font-size:1px;line-height:16px;">&nbsp;</td></tr>

        <tr><td style="padding:0 16px;font-family:Tahoma,Arial,sans-serif;font-size:12px;color:${C.ink};font-weight:700;line-height:1.4;">${item.name}</td></tr>

        <tr><td height="12" style="font-size:1px;line-height:12px;">&nbsp;</td></tr>

        <tr><td style="padding:0 16px;">
          <table width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
            <td valign="bottom" style="font-family:Tahoma,Arial,sans-serif;font-size:24px;color:${C.ink};font-weight:700;line-height:1;">
              ${item.completed_count}<span style="font-size:12px;color:${C.muted};font-weight:400;"> / ${item.target}</span>
            </td>
            <td valign="bottom" align="left" style="font-family:Tahoma,Arial,sans-serif;font-size:16px;color:${accent};font-weight:700;">${pct}%</td>
          </tr></table>
        </td></tr>

        <tr><td height="12" style="font-size:1px;line-height:12px;">&nbsp;</td></tr>

        <tr><td style="padding:0 16px;">
          <table width="100%" cellpadding="0" cellspacing="0" border="0" dir="rtl" style="border-collapse:collapse;">
            <tr>${barFillCell}${barEmptyCell}</tr>
          </table>
        </td></tr>

        <tr><td height="10" style="font-size:1px;line-height:10px;">&nbsp;</td></tr>

        <tr><td style="padding:0 16px;">
          <table width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
            <td style="font-family:Tahoma,Arial,sans-serif;font-size:10px;color:${accent};font-weight:600;letter-spacing:0.3px;">${statusLabel}</td>
            <td align="left" style="font-family:Tahoma,Arial,sans-serif;font-size:10px;color:${C.muted};">متبقي: ${item.remaining_to_target}</td>
          </tr></table>
        </td></tr>

        <tr><td height="16" style="font-size:1px;line-height:16px;">&nbsp;</td></tr>

      </table>
    </td>`;
};

// ✅ Project Table Row
const projectTableRow = (p, i, dateColor) => {
  const bgColor = i%2 ? C.card : '#ffffff';
  return `
  <tr bgcolor="${bgColor}" style="background-color:${bgColor};">
    <td style="padding:10px 12px;font-size:12px;color:${C.ink};border-bottom:1px solid ${C.border};font-family:Tahoma,Arial,sans-serif;">${p.project_name || '-'}</td>
