const categoriesSorted = Object.entries(breakdowns.window_by_category || {}).sort((a,b)=>b[1]-a[1]);
const maxCat = categoriesSorted[0] ? categoriesSorted[0][1] : 1;
const categoryBars = categoriesSorted.length
  ? categoriesSorted.map(([name, count]) => progressBar(name, count, maxCat, C.navy)).join('')
  : `<tr><td style="padding:14px;text-align:center;color:${C.muted};font-size:12px;font-family:Tahoma,Arial,sans-serif;">لا توجد مشاريع ضمن النافذة الحالية</td></tr>`;

const topMembers = (breakdowns.window_top_members || []).slice(0, 6);
const maxMem = topMembers[0] ? topMembers[0].count : 1;
const memberBars = topMembers.length
  ? topMembers.map(m => progressBar(m.member, m.count, maxMem, C.gold)).join('')
  : `<tr><td style="padding:14px;text-align:center;color:${C.muted};font-size:12px;font-family:Tahoma,Arial,sans-serif;">لا توجد بيانات أعضاء</td></tr>`;

const initiativesRow1 = targetInitiatives.slice(0, 3).map(initiativeCard).join('');
const initiativesRow2 = targetInitiatives.slice(3, 6).map(initiativeCard).join('');
const totalCompleted = targetInitiatives.reduce((a, b) => a + b.completed_count, 0);
const totalTarget    = targetInitiatives.reduce((a, b) => a + b.target, 0);
const overallRate    = totalTarget ? Math.round((totalCompleted / totalTarget) * 100) : 0;
const totalRemaining = Math.max(totalTarget - totalCompleted, 0);

const recommendationsHtml = aiRecommendations.map((rec, i) => `
  <tr><td style="padding:10px 0;font-family:Tahoma,Arial,sans-serif;">
